import {
    Table,
    ReferenceColumn,
    IntegerColumn,
    GuidColumn,
    StringColumn,
    DateTimeColumn,
    DomainIdColumn,
    DomainPathColumn,
} from '@servicenow/sdk/core'

export const kb_article_checklist_summary = Table({
    actions: ['read', 'update', 'create'],
    allowClientScripts: true,
    allowNewFields: true,
    allowUiActions: true,
    allowWebServiceAccess: true,
    autoNumber: {
        number: 100000,
        prefix: 'QUE',
    },
    display: 'aqi_score',
    label: 'Article Checklist Summary',
    name: 'kb_article_checklist_summary',
    schema: {
        version_author: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                readonly_clickthrough: true,
            },
            label: 'Version Author',
            readOnly: true,
            referenceTable: 'sys_user',
        }),
        aqi_score: IntegerColumn({
            label: 'AQI Score',
            readOnly: true,
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        comments_for_author_reviser: StringColumn({
            label: 'Comments for Author/Version Author',
            maxLength: 4000,
        }),
        sys_updated_on: DateTimeColumn({
            label: [
                {
                    label: 'Updated',
                    plural: 'Updated',
                    language: 'en',
                },
            ],
        }),
        reviewer: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                readonly_clickthrough: true,
            },
            label: 'Reviewer',
            mandatory: true,
            readOnly: true,
            referenceTable: 'sys_user',
        }),
        sys_domain: DomainIdColumn({
            label: [
                {
                    hint: 'Domain to which the Article Checklist Summary belongs',
                    label: 'Domain',
                    plural: 'Domains',
                    language: 'en',
                },
            ],
        }),
        sys_created_on: DateTimeColumn({
            label: [
                {
                    label: 'Created',
                    plural: 'Created',
                    language: 'en',
                },
            ],
        }),
        number: StringColumn({
            attributes: {
                ignore_filter_on_new: true,
            },
            default: 'javascript:global.getNextObjNumberPadded();',
            label: 'Number',
            readOnly: true,
            unique: true,
        }),
        comments_for_reviewers: StringColumn({
            label: 'Comments for Reviewers',
            maxLength: 4000,
        }),
        sys_created_by: StringColumn({
            label: [
                {
                    label: 'Created by',
                    plural: 'Created by',
                    language: 'en',
                },
            ],
        }),
        article: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                readonly_clickthrough: true,
            },
            label: 'Article',
            mandatory: true,
            readOnly: true,
            referenceTable: 'kb_knowledge',
        }),
        sys_mod_count: IntegerColumn({
            label: [
                {
                    label: 'Updates',
                    plural: 'Updates',
                    language: 'en',
                },
            ],
        }),
        checklist: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                readonly_clickthrough: true,
            },
            label: 'Checklist',
            mandatory: true,
            readOnly: true,
            referenceTable: 'kb_quality_checklist',
        }),
        state: StringColumn({
            dropdown: 'dropdown_with_none',
            label: 'State',
            readOnly: true,
        }),
        sys_updated_by: StringColumn({
            label: [
                {
                    label: 'Updated by',
                    plural: 'Updated by',
                    language: 'en',
                },
            ],
        }),
        sys_domain_path: DomainPathColumn({
            attributes: {
                case_sensitive: true,
            },
            default: '/',
            label: 'Domain Path',
        }),
    },
})
